# R93 blind predictions B21+B22. Writes only own predictions, verifies by exact ids.
import json, pathlib
BASE = pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round93/predictions")
BASE.mkdir(parents=True, exist_ok=True)

def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}

def W(cid, text, basis, conf, trig):
    p = BASE / f"{cid}.json"
    obj = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": trig}
    p.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")

